class EngineModule18:
    """Implementation of EngineModule18 supporting process(data) and get_status()."""

    def __init__(self):
        self._status = "ready"
        self._last_processed = None

    def process(self, data):
        """Processes the given data and updates internal state."""
        self._last_processed = data
        self._status = "processed"
        if isinstance(data, dict):
            res = data.copy()
        else:
            res = {"input": data}
        res["status"] = "success"
        return res

    def get_status(self):
        """Returns the current status of the engine module."""
        return self._status
